xpath.script:
{
    "@context": "https://schema.org",
    "@type": "WebSite",
    "name": "ChaosHub - ERP Knowledge Hub",
    "url": "",
    "description": "Free ERP education for Sri Lankan businesses",
    "inLanguage": "en-LK",
    "potentialAction": {
        "@type": "SearchAction",
        "target": {
            "@type": "EntryPoint",
            "urlTemplate": "knowledge?search={search_term_string}"
        },
        "query-input": "required name=search_term_string"
    }
}

{
    "@context": "https://schema.org",
    "@type": "CollectionPage",
    "name": "ERP Knowledge Base",
    "description": "Comprehensive collection of ERP tutorials and business systems guides",
    "url": "knowledge",
    "inLanguage": "en-LK",
    "isPartOf": {
        "@type": "WebSite",
        "name": "ChaosHub",
        "url": ""
    }
}

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "name": "Help & Support - Frequently Asked Questions",
    "description": "Common questions about ERP systems, Odoo, and digital transformation",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "What is ERP?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Enterprise Resource Planning (ERP) is integrated management software that helps businesses manage core processes like accounting, inventory, sales, HR, and manufacturing in one unified system."
            }
        },
        {
            "@type": "Question",
            "name": "Why should I use Odoo for my business?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Odoo is a comprehensive open-source ERP that offers flexibility, cost-effectiveness, and extensive customization options. It's ideal for businesses of all sizes in Sri Lanka looking for modern business management software."
            }
        },
        {
            "@type": "Question",
            "name": "Is ChaosHub affiliated with Odoo?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "No, ChaosHub is an independent educational platform. We provide vendor-neutral information to help businesses make informed decisions about ERP systems."
            }
        }
    ]
}

{
    "@context": "https://schema.org",
    "@type": "ContactPage",
    "name": "Contact Us - ChaosHub",
    "description": "Get in touch with ChaosHub for ERP guidance and business transformation support",
    "url": "contactus",
    "mainEntity": {
        "@type": "Organization",
        "name": "ChaosHub",
        "email": "info@chaoshub.lk",
        "url": ""
    }
}

{
    "@context": "https://schema.org",
    "@type": "Service",
    "serviceType": "ERP Education and Consulting",
    "provider": {
        "@type": "EducationalOrganization",
        "name": "ChaosHub"
    },
    "areaServed": {
        "@type": "Country",
        "name": "Sri Lanka"
    },
    "hasOfferCatalog": {
        "@type": "OfferCatalog",
        "name": "ERP Services",
        "itemListElement": [
            {
                "@type": "Offer",
                "itemOffered": {
                    "@type": "Service",
                    "name": "ERP Education",
                    "description": "Free educational resources about ERP systems"
                }
            },
            {
                "@type": "Offer",
                "itemOffered": {
                    "@type": "Service",
                    "name": "Digital Transformation Guidance",
                    "description": "Vendor-neutral consulting for business digitalization"
                }
            }
        ]
    }
}
